{"success": true, "data": {"stdout": "# lm-evaluation-harness integration for KL-distilled sparse Llama-3.1-8B.
# Modified: added --allocation_strategy flag (global | uniform) for ablation study.
#   global  — TEAL-style single threshold across all layers (original, uneven per-layer sparsity)
#   uniform — each layer independently does top-k, every layer has exactly sparsity_target
# Added --compare flag: prints per-layer sparsity for BOTH strategies side-by-side.
# Input: predictor checkpoint, model path, task list, allocation strategy
# Output: lm-eval results JSON in --output_path
# Dependencies: lm-eval >= 0.4, transformers, torch, datasets

import argparse
import importlib.util
import json
import os
import sys

import torch
from transformers import AutoModelForCausalLM, AutoTokenizer

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from data_utils import get_eval_dataset
from predictor import PredictorWrapper


def _best_attn_impl():
    if importlib.util.find_spec("flash_attn"):
        return "flash_attention_2"
    return "sdpa"


def _global_topk_masks(layer_scores, sparsity_target):
    """Global allocation: normalize per-layer means, single threshold across all layers."""
    items = sorted(layer_scores.items())
    normalized = []
    for li, s in items:
        s_f = s.float()
        mu = s_f.mean()
        normalized.append((li, s_f / mu if mu > 1e-12 else s_f))
    all_s = torch.cat([s for _, s in normalized])
    num_keep = int(len(all_s) * (1.0 - sparsity_target))
    thr = torch.topk(all_s, num_keep).values[-1]
    return {li: (s >= thr).to(torch.bfloat16) for li, s in normalized}


def _uniform_topk_masks(layer_scores, sparsity_target):
    """Uniform per-layer allocation: each layer independently keeps top-(1-sparsity) neurons.

    Unlike global top-k which concentrates sparsity in later layers (Layer 26-31: 41-70%),
    this ensures every layer has exactly the same sparsity = sparsity_target.
    """
    masks = {}
    for li in sorted(layer_scores):
        s = layer_scores[li].float()
        num_keep = int(len(s) * (1.0 - sparsity_target))
        if num_keep >= len(s):
            masks[li] = torch.ones_like(s, dtype=torch.bfloat16)
        elif num_keep <= 0:
            masks[li] = torch.zeros_like(s, dtype=torch.bfloat16)
        else:
            thr = torch.topk(s, num_keep).values[-1]
            masks[li] = (s >= thr).to(torch.bfloat16)
    return masks


def compute_layer_scores(wrapper, input_ids, calib_batch_size=4):
    """Compute per-layer importance scores from predictor + dense intermediates."""
    accum_scores = {}
    n_batches = 0

    for start in range(0, input_ids.size(0), calib_batch_size):
        batch = input_ids[start:start + calib_batch_size]
        wrapper.forward_dense(batch, capture_intermediates=True)
        intermediates = wrapper.get_intermediates()
        layer_inputs = wrapper.get_layer_inputs()
        with torch.no_grad():
            for layer_idx in range(len(wrapper.predictors)):
                if layer_idx not in layer_inputs or layer_idx not in intermediates:
                    continue
                logits = wrapper.predictors[layer_idx](layer_inputs[layer_idx])
                hard_mask = (logits > 0).float()
                mag = intermediates[layer_idx].abs().float()
                scores = (mag * hard_mask).mean(dim=(0, 1))
                if layer_idx not in accum_scores:
                    accum_scores[layer_idx] = scores
                else:
                    accum_scores[layer_idx] = accum_scores[layer_idx] + scores
        n_batches += 1

    return {li: accum_scores[li] / n_batches for li in sorted(accum_scores)}


def teal_masks(layer_scores, sparsity_target, allocation_strategy="global"):
    """Dispatch to global or uniform mask generation from pre-computed scores."""
    if allocation_strategy == "global":
        return _global_topk_masks(layer_scores, sparsity_target)
    elif allocation_strategy == "uniform":
        return _uniform_topk_masks(layer_scores, sparsity_target)
    else:
        raise ValueError(f"Unknown allocation_strategy: {allocation_strategy}. Use 'global' or 'uniform'.")


